# middleware/tenant_middleware.py
import threading
from fastapi import Depends, HTTPException, Request
from ai_orchestrator.models import Tenant
from database import SessionLocal

thread_local = threading.local()

def get_tenant_id():
    return getattr(thread_local, 'tenant_id', None)

def set_tenant_id(tenant_id):
    thread_local.tenant_id = tenant_id

def tenant_middleware(request: Request, db: SessionLocal = Depends(get_db)):
    auth_header = request.headers.get('X-Tenant-ID')
    if not auth_header:
        raise HTTPException(status_code=401, detail="Tenant ID required")
    
    tenant_id = int(auth_header)
    set_tenant_id(tenant_id)
    
    # Validate tenant exists (basic check)
    tenant = db.query(Tenant).get(tenant_id)
    if not tenant:
        raise HTTPException(status_code=404, detail="Tenant not found")
    
    return tenant

# services/stripe_service.py
import stripe
from ai_orchestrator.models import TenantSubscription, SubscriptionPlan
from database import SessionLocal

stripe.api_key = "sk_test_..."

def create_customer(tenant_id: int, email: str):
    db = SessionLocal()
    tenant = db.query(Tenant).get(tenant_id)
    customer = stripe.Customer.create(
        email=email,
        metadata={'tenant_id': str(tenant_id)}
    )
    return customer

def create_subscription(tenant_id: int, plan_id: int):
    db = SessionLocal()
    plan = db.query(SubscriptionPlan).get(plan_id)
    customer = create_customer(tenant_id, "tenant@example.com")
    
    subscription = stripe.Subscription.create(
        customer=customer.id,
        items=[{"price": plan.stripe_price_id}],
        expand=["latest_invoice.payment_intent"]
    )
    
    db_subscription = TenantSubscription(
        tenant_id=tenant_id,
        plan_id=plan_id,
        stripe_subscription_id=subscription.id
    )
    db.add(db_subscription)
    db.commit()
    return db_subscription

def handle_webhook(event):
    if event.type == "invoice.payment_succeeded":
        subscription_id = event.data.object.subscription
        tenant_subscription = db.query(TenantSubscription).filter_by(stripe_subscription_id=subscription_id).first()
        if tenant_subscription:
            tenant_subscription.status = "active"
            db.commit()
    elif event.type == "customer.subscription.deleted":
        subscription_id = event.data.object.id
        tenant_subscription = db.query(TenantSubscription).filter_by(stripe_subscription_id=subscription_id).first()
        if tenant_subscription:
            tenant_subscription.status = "canceled"
            db.commit()

# tasks/billing_tasks.py
from celery import Celery
from ai_orchestrator.models import UsageLog, TenantSubscription
from database import SessionLocal
from services.stripe_service import charge_tenant

celery = Celery('billing', broker='redis://localhost:6379/0')

@celery.task
def process_usage_logs():
    db = SessionLocal()
    logs = db.query(UsageLog).filter_by(billed=False).all()
    
    for log in logs:
        tenant = log.tenant
        subscription = tenant.subscription
        
        if subscription.status != "active":
            continue
            
        # Apply tiered pricing
        if subscription.plan.monthly_document_limit > 0:
            usage_count = db.query(UsageLog).filter_by(tenant_id=tenant.id).count()
            if usage_count > subscription.plan.monthly_document_limit:
                overage = usage_count - subscription.plan.monthly_document_limit
                charge_amount = overage * subscription.plan.price_per_document * 0.3  # 30% rate for overage
                charge_tenant(tenant.id, charge_amount)
                
        log.billed = True
        db.commit()

