import pytest
from ai_orchestrator.models import Tenant, User, Document
from database import SessionLocal, engine
from fastapi.testclient import TestClient
from main import app
from middleware.tenant_middleware import tenant_middleware, set_tenant_id

@pytest.fixture
def test_db():
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    yield db
    Base.metadata.drop_all(bind=engine)
    db.close()

def test_tenant_isolation(test_db):
    # Create tenants
    tenant1 = Tenant(name="Tenant A")
    tenant2 = Tenant(name="Tenant B")
    test_db.add_all([tenant1, tenant2])
    test_db.commit()
    
    # Create users
    user1 = User(email="user1@example.com", tenant_id=tenant1.id)
    user2 = User(email="user2@example.com", tenant_id=tenant2.id)
    test_db.add_all([user1, user2])
    test_db.commit()
    
    # Test tenant1 can only see their users
    set_tenant_id(tenant1.id)
    users = test_db.query(User).all()
    assert len(users) == 1
    assert users[0].email == "user1@example.com"
    
    # Test tenant2 can only see their users
    set_tenant_id(tenant2.id)
    users = test_db.query(User).all()
    assert len(users) == 1
    assert users[0].email == "user2@example.com"

